class OrderQuantityManager {
    private List<Order> items;
    private String status;

    public OrderQuantityManager() {
        this.items = new ArrayList<>();
        this.status = "open";
    }

    public void addItem(String name, int quantity, float price) {
        Order item = new Order(name, quantity, price);
        this.items.add(item);
    }

    public List<Order> getItems() {
        return items;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }
}

class PriceCalculator {
    public static float calculateTotal(OrderQuantityManager orderManager) {
        float total = 0;
        for (Order item : orderManager.getItems()) {
            total += item.getQuantity() * item.getPrice();
        }
        return total;
    }
}
